<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,userId?:string}>()
const stats=ref<Row>({}),records=ref<Row[]>([]),users=ref<Row[]>([]),filter=ref(props.userId??''),error=ref(''),loading=ref(false),last=ref('')
const bytes=(n:any)=>{const v=Number(n??0);return v>=1073741824?(v/1073741824).toFixed(2)+' GiB':v>=1048576?(v/1048576).toFixed(1)+' MiB':v>=1024?(v/1024).toFixed(1)+' KiB':v+' B'}
const resets:Record<string,string>={never:'不自动重置',daily:'每天',monthly:'每月 1 日',rolling_monthly:'按起点每月'}
const selected=computed(()=>users.value.find(u=>u.id===filter.value)),allocated=computed(()=>Number(stats.value.allocated_bytes??0)),used=computed(()=>Number(stats.value.used_bytes??0))
const chart=computed(()=>{const d=stats.value.daily??[];const max=Math.max(1,...d.map((v:Row)=>Number(v.uplink)+Number(v.downlink)));return d.map((v:Row)=>({...v,height:Math.max(3,(Number(v.uplink)+Number(v.downlink))/max*100)}))})
let alive=true,timer:ReturnType<typeof setTimeout>,sequence=0
async function load(){loading.value=true;const seq=++sequence;try{const [a,b,c]=await Promise.all([props.api('dashboard'),props.api('access-records'+(filter.value?'?user_id='+filter.value:'')),props.api('proxy-users')]);if(!alive||seq!==sequence)return;stats.value=a;records.value=b;users.value=c;last.value=new Date().toLocaleTimeString();error.value=''}catch(e){if(alive&&seq===sequence)error.value=String(e)}finally{if(alive&&seq===sequence)loading.value=false}}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden')await load();if(alive)schedule()},30000)}
onMounted(()=>{void load();schedule()});onUnmounted(()=>{alive=false;sequence++;clearTimeout(timer)})
</script>
<template><div class="traffic-workspace"><div class="traffic-toolbar"><p class="muted">{{last?'最近更新 '+last:'等待统计数据'}} · 上传 + 下载合计 · GiB = 1024³ 字节</p><button class="secondary" :disabled="loading" @click="load">刷新统计</button></div><p v-if="error" class="error" role="alert">{{error}}</p>
<div class="traffic-stats"><article><small>今日代理流量</small><strong>{{bytes(stats.today_bytes)}}</strong><span>北京时间自然日 · 各入站合计（链路逐跳计）</span></article><article><small>用户本期已用</small><strong>{{bytes(used)}}</strong><span>个人重置周期内的流量</span></article><article><small>已分配额度</small><strong>{{bytes(allocated)}}</strong><span>不包含无限流量用户</span></article><article><small>在线用户 / 总用户</small><strong>{{stats.online_users??0}} <em>/ {{stats.users??0}}</em></strong><span>{{stats.limited_users??0}} 人额度耗尽 · 近 60 秒有流量</span></article></div>
<div class="traffic-overview"><section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">BANDWIDTH / LAST 14 DAYS</span><h2>流量趋势</h2></div><span class="status succeeded">{{stats.online_hosts??0}} / {{stats.hosts??0}} 主机在线</span></div><div v-if="chart.length" class="traffic-chart"><div v-for="d in chart" :key="d.day" class="chart-day" :title="d.day+' · '+bytes(Number(d.uplink)+Number(d.downlink))"><div class="bar-track"><i :style="{height:d.height+'%'}"></i></div><small>{{d.day?.slice(5)}}</small></div></div><div v-else class="console-empty">从本版本统计启用后开始累计，历史流量无法追溯。</div></section>
<section class="panel publish-card"><span class="eyebrow">NATIVE TELEMETRY</span><h2>采集与运行</h2><p><b>{{stats.running_inbounds??0}}</b> 个已应用的运行入站</p><div v-for="m in stats.telemetry??[]" :key="m.host_id+m.engine" class="meter-row"><span>{{m.host_name}}<small class="block-muted">{{m.engine}}</small></span><span :class="['status',m.fresh===true?'succeeded':'pending']">{{m.fresh===true?'采集中':'等待 / 不可用'}}</span></div><p class="muted">内核提供真实计数，约 10 秒上报。短时在途流量、进程异常退出可能造成少量误差。共享密钥协议单独统计入口流量。</p></section></div>
<section class="panel publish-card"><span class="eyebrow">INBOUNDS / TRANSFER</span><h2>各入口流量</h2><p class="muted">自启用本版统计后累计。链式代理每一跳分别计量；入口总量与用户账单分别汇总，不叠加收费。共享密钥入口也可在这里查看。</p><div class="table-scroll"><table><thead><tr><th>入口 / 主机</th><th>协议 / 内核</th><th>上传</th><th>下载</th><th>合计</th></tr></thead><tbody><tr v-for="i in stats.inbound_usage??[]" :key="i.id"><td>{{i.name}}<small class="block-muted">{{i.host_name}}</small></td><td>{{i.kind}}<small class="block-muted">{{i.engine}}</small></td><td>{{bytes(i.uplink)}}</td><td>{{bytes(i.downlink)}}</td><td>{{bytes(Number(i.uplink)+Number(i.downlink))}}</td></tr></tbody></table></div><p v-if="!stats.inbound_usage?.length" class="console-empty">尚未配置代理入口。</p></section>
<section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">USERS / QUOTAS</span><h2>用户流量与额度</h2></div></div><div class="table-scroll"><table><thead><tr><th>用户</th><th>本期已用 / 分配</th><th>剩余额度</th><th>重置周期</th><th>累计已用</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><button class="text-button" @click="filter=u.id;load()">{{u.name}}</button><small class="block-muted">{{u.limited?'额度耗尽':u.active?'有效':u.enabled?'已到期':'已停用'}}</small></td><td>{{bytes(u.used_bytes)}} / {{u.quota_bytes?bytes(u.quota_bytes):'不限'}}<progress v-if="u.quota_bytes" :value="u.used_bytes" :max="u.quota_bytes"></progress></td><td>{{u.quota_bytes?bytes(Math.max(0,u.quota_bytes-u.used_bytes)):'不限'}}</td><td>{{resets[u.reset_strategy]??'不自动重置'}}</td><td>{{bytes(u.lifetime_bytes)}}</td></tr></tbody></table></div><p v-if="!users.length" class="console-empty">添加用户并分配入站后，可设置流量额度与重置周期。</p></section>
<section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">CONNECTION METADATA / LAST 7 DAYS</span><h2>访问目标与来源 IP</h2></div><label>筛选用户<select v-model="filter" @change="load"><option value="">所有用户 / 共享入口</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.name}}</option></select></label></div><p class="muted">{{selected?'当前用户：'+selected.name+'。':''}}仅显示代理连接元数据，每轮最多记录 100 条，最多保留 7 天 / 20,000 条，当前查询最近 200 条。目标可能是域名或 IP，不包含 HTTPS 页面内容和完整 URL。</p><div class="table-scroll"><table><thead><tr><th>时间</th><th>用户 / 入口</th><th>来源 IP</th><th>目标域名 / IP</th><th>协议</th></tr></thead><tbody><tr v-for="r in records" :key="r.host_id+r.event_id"><td>{{new Date(r.observed_at).toLocaleString()}}</td><td>{{r.user_name||'共享密钥 / 未识别用户'}}<small class="block-muted">{{r.host_name}} · {{r.service_name||'已移除入口'}}</small></td><td><code>{{r.source_ip}}</code></td><td>{{r.destination}}:{{r.destination_port}}</td><td>{{r.network?.toUpperCase()}}</td></tr></tbody></table></div><p v-if="!records.length" class="console-empty">尚无连接记录。统计从 Agent 0.10 升级完成后开始采集。</p></section></div></template>
<style scoped>.traffic-workspace{display:grid;gap:22px}.traffic-toolbar{display:flex;justify-content:space-between;gap:20px;align-items:center}.traffic-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.traffic-stats article{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:23px}.traffic-stats small{color:var(--muted);font-size:12px}.traffic-stats strong{display:block;font-size:27px;margin:13px 0 10px;letter-spacing:-1px}.traffic-stats span{font-size:10px;color:var(--muted)}.traffic-stats em{font-size:15px;font-style:normal;color:var(--muted)}.traffic-overview{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.traffic-chart{height:170px;display:flex;gap:10px;align-items:flex-end;padding-top:15px}.chart-day{flex:1;min-width:0;text-align:center}.bar-track{height:125px;display:flex;align-items:flex-end;justify-content:center}.bar-track i{display:block;width:min(100%,34px);background:linear-gradient(var(--accent),color-mix(in srgb,var(--accent) 35%,transparent));border-radius:5px 5px 0 0}.chart-day small{font-size:9px;color:var(--muted);white-space:nowrap}.meter-row{display:flex;justify-content:space-between;align-items:center;padding:13px 0;border-top:1px solid var(--line);gap:15px;font-size:12px}progress{display:block;width:140px;height:5px;margin-top:8px;accent-color:var(--accent)}select{background:var(--input);color:var(--ink);padding:9px;border:1px solid var(--line);border-radius:7px;font-size:12px;margin-left:8px}@media(max-width:1100px){.traffic-stats{grid-template-columns:repeat(2,1fr)}.traffic-overview{grid-template-columns:1fr}}@media(max-width:650px){.traffic-stats{gap:10px}.traffic-stats article{padding:17px}.traffic-stats strong{font-size:22px}.traffic-toolbar{align-items:flex-start}.traffic-chart{gap:4px}.chart-day small{font-size:8px}}</style>
